import torch
import torch.nn as nn

class ResidualBlock(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.linear = nn.Linear(dim, dim)

    def forward(self, x):
        return x + self.linear(x)

block = ResidualBlock(10)
x = torch.randn(5, 10)
output = block(x)
print(output.shape == x.shape)

