import tensorflow as tf

class GatedLinearUnit(tf.keras.layers.Layer):
    def call(self, x):
        value, gate = tf.split(x, 2, axis=-1)
        return value * tf.sigmoid(gate)

layer = GatedLinearUnit()
input_tensor = tf.constant([[1.0, 2.0, 0.0, -1.0]])
output = layer(input_tensor)
print(tf.reduce_sum(output) > 0)

import torch

# Differentiable neural computer interface
class DNCAccess(torch.nn.Module):
    def __init__(self, memory_size, vector_size):
        super().__init__()
        self.memory = torch.nn.Parameter(torch.randn(memory_size, vector_size))

    def forward(self, key, strength):
        similarity = torch.matmul(key, self.memory.t())
        return torch.softmax(similarity * strength, dim=-1)

access = DNCAccess(100, 50)
key = torch.randn(1, 50)
result = access(key, 1.0)
print(torch.allclose(result.sum(), torch.tensor(1.0)))

