# Neural field dynamics
class NeuralField(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.w_exc = 1.0
        self.w_inh = -0.8

    def interaction_kernel(self, distance):
        return self.w_exc * torch.exp(-distance**2/2) + self.w_inh * torch.exp(-distance**2/8)

distances = torch.tensor([0.0, 1.0, 2.0])
kernel_values = NeuralField().interaction_kernel(distances)
print(kernel_values[0] > kernel_values[2])

