# Molecular computing reaction kinetics
class ChemicalReaction:
    def __init__(self, rate_constant):
        self.k = rate_constant

    def forward_rate(self, A_conc, B_conc):
        return self.k * A_conc * B_conc

rxn = ChemicalReaction(0.1)
rate = rxn.forward_rate(2.0, 3.0)
print(rate == 0.6)

import numpy as np

# Granular computing: particle flow dynamics
class GranularLogic:
    def __init__(self, n_particles):
        self.positions = np.random.rand(n_particles)

    def apply_pressure(self, force_direction):
        # Simplified granular flow
        self.positions += 0.1 * force_direction
        self.positions = np.clip(self.positions, 0, 1)
        return np.mean(self.positions)

granules = GranularLogic(1000)
result = granules.apply_pressure(0.5)
print(result > 0.5)

