# Developmental network growth rule
class NeuriteGrowth:
    def __init__(self, sensitivity):
        self.sensitivity = sensitivity

    def growth_direction(self, chemical_gradient):
        # Chemotaxis-like growth
        return np.tanh(self.sensitivity * chemical_gradient)

growth = NeuriteGrowth(2.0)
direction = growth.growth_direction(1.0)
print(direction > 0.9)

import numpy as np

# Multi-agent system: Boid simulation
class Boid:
    def __init__(self, position):
        self.position = np.array(position, dtype=float)

    def separation(self, neighbors, desired_separation):
        if len(neighbors) == 0:
            return np.zeros(2)
        avg_vector = np.mean([n.position - self.position for n in neighbors], axis=0)
        return -avg_vector / np.linalg.norm(avg_vector + 1e-8)

boid = Boid([0, 0])
neighbors = [Boid([1, 1]), Boid([-1, -1])]
sep_force = boid.separation(neighbors, 2.0)
print(np.all(np.isfinite(sep_force)))
